def DesiredProperty (E : Type*) [NormedAddCommGroup E] [NormedSpace ℝ E] : Prop :=
  ∀ e : ℕ → E →L[ℝ] ℝ, IsNorming e →
    ∃ f : E, ¬ ∃ g : E, ∀ n, e n g = |e n f|

